/**
 * @file    motor.c
 *
 * @brief   Motor control module.
 *
 * @details This module provides functions to initialize and control a motor
 *          using PWM signals generated by a hardware timer.
 *
 *          Motor speed is controlled through the PWM pulse width, while
 *          direction is selected by enabling the corresponding timer channel.
 *
 * @author  Julen Gallastegui de la Cruz
 * @author  Andrea Nieto Gil
 */

/* Includes -----------------------------------------------------------------*/

#include "main.h"
#include "motor.h"

/* Private function prototypes ---------------------------------------------*/
static inline void MOTOR_Stop_Pwm(TIM_HandleTypeDef * timer, uint8_t channel);

static inline void MOTOR_Set_Pwm(TIM_HandleTypeDef * timer, uint8_t channel,
                                 uint16_t pulse);

/* Public functions ---------------------------------------------------------*/

/**
 * @brief   Initializes a motor instance.
 *
 * @details Configures the timer and its associated channels for forward and
 *          backward operation. The motor is initialized in a stopped state.
 *
 * @param[in] timer               Pointer to the timer handle.
 * @param[in] channel_forwards    Timer channel used for forward rotation.
 * @param[in] channel_backwards   Timer channel used for backward rotation.
 * @param[out] output             Pointer to the motor instance to initialize.
 *
 * @note    Both PWM channels are stopped during initialization.
 */
void MOTOR_Create(TIM_HandleTypeDef * timer, uint8_t channel_forwards,
                  uint8_t channel_backwards, motor_t * output)
{
    output->timer = timer;
    output->channel_forwards = channel_forwards;
    output->channel_backwards = channel_backwards;
    output->speed = 0U;
    output->direction = 0;

    MOTOR_Stop_Pwm(timer, channel_forwards);
    MOTOR_Stop_Pwm(timer, channel_backwards);
}

/**
 * @brief   Updates the motor speed and direction.
 *
 * @details Activates the PWM channel corresponding to the requested
 *          direction and stops the opposite channel.
 *
 *          If the requested speed and direction are identical to the
 *          current motor configuration, no changes are performed.
 *
 * @param[in,out] motor       Pointer to the motor instance.
 * @param[in]     speed       Requested PWM pulse width.
 * @param[in]     direction   Requested motor rotation direction.
 *
 * @note    Only one PWM channel is active at a time.
 */
void MOTOR_Update(motor_t * motor, uint16_t speed,
                  motor_direction_t direction)
{
    /* Limit max speed */
    if(speed > PWM_ARR)
      speed = PWM_ARR;

    /* Avoid unnecessary PWM reconfiguration. */
    if ((motor->speed == speed) && (motor->direction == direction))
    {
        return;
    }

    /* Configure the PWM output according to the requested direction. */
    if (direction == MOTOR_FORWARD)
    {
        MOTOR_Stop_Pwm(motor->timer, motor->channel_backwards);
        MOTOR_Set_Pwm(motor->timer, motor->channel_forwards, speed);
    }
    else
    {
        MOTOR_Stop_Pwm(motor->timer, motor->channel_forwards);
        MOTOR_Set_Pwm(motor->timer, motor->channel_backwards, speed);
    }

    /* Update the motor state. */
    motor->speed = speed;
    motor->direction = direction;
}

/* Private functions --------------------------------------------------------*/

/**
 * @brief   Stops PWM generation on a timer channel.
 *
 * @details Sets the channel compare value to zero and stops PWM generation.
 *
 * @param[in] timer    Pointer to the timer handle.
 * @param[in] channel  Timer channel to stop.
 */
static inline void MOTOR_Stop_Pwm(TIM_HandleTypeDef *timer, uint8_t channel)
{
    __HAL_TIM_SetCompare(timer, channel, 0U);
    HAL_TIM_PWM_Stop(timer, channel);
}

/**
 * @brief   Sets the PWM pulse width and starts PWM generation.
 *
 * @details Updates the timer compare register, resets the timer counter
 *          and starts PWM generation on the specified channel.
 *
 * @param[in] timer    Pointer to the timer handle.
 * @param[in] channel  Timer channel to configure.
 * @param[in] pulse    PWM pulse width to apply.
 */
static inline void MOTOR_Set_Pwm(TIM_HandleTypeDef * timer, uint8_t channel,
                                 uint16_t pulse)
{
    __HAL_TIM_SetCompare(timer, channel, pulse);
    __HAL_TIM_SetCounter(timer, 0U);
    HAL_TIM_PWM_Start(timer, channel);
}

/*** end of file ***/
